const data = require('fs').readFileSync(0);
let pos = 0;
function nextInt() {
  while (pos < data.length && (data[pos] < 48 || data[pos] > 57)) pos++;
  let x = 0;
  while (pos < data.length && data[pos] >= 48 && data[pos] <= 57) {
    x = x * 10 + (data[pos] - 48);
    pos++;
  }
  return x;
}

const MOD = 998244353;
function mul(a, b) {
  const ah = Math.floor(a / 65536), al = a % 65536;
  return ((ah * b % MOD) * 65536 + al * b) % MOD;
}

const n = nextInt();
if (n === 1) {
  process.stdout.write("1\n");
} else {
  const m = n - 1;
  const us = new Int32Array(m), vs = new Int32Array(m);
  const start = new Int32Array(n + 1);
  for (let i = 0; i < m; i++) {
    const u = nextInt() - 1, v = nextInt() - 1;
    us[i] = u; vs[i] = v;
    start[u + 1]++; start[v + 1]++;
  }
  for (let i = 0; i < n; i++) start[i + 1] += start[i];
  const cursor = new Int32Array(n);
  for (let i = 0; i < n; i++) cursor[i] = start[i];
  const adj = new Int32Array(2 * m);
  for (let i = 0; i < m; i++) {
    adj[cursor[us[i]]++] = vs[i];
    adj[cursor[vs[i]]++] = us[i];
  }

  const order = new Int32Array(n);
  const par = new Int32Array(n).fill(-1);
  const stack = new Int32Array(n);
  let sp = 0, cnt = 0;
  stack[sp++] = 0;
  par[0] = -1;
  while (sp > 0) {
    const v = stack[--sp];
    order[cnt++] = v;
    for (let i = start[v]; i < start[v + 1]; i++) {
      const u = adj[i];
      if (u !== par[v]) {
        par[u] = v;
        stack[sp++] = u;
      }
    }
  }

  const A = new Int32Array(n); // v matched, component perfect matching
  const B = new Int32Array(n); // v isolated (component = {v})
  const C = new Int32Array(n); // v unmatched, component size >= 2, rest matched

  for (let idx = n - 1; idx >= 0; idx--) {
    const v = order[idx];
    let S0 = 1, S1 = 0, S2 = 0;
    const p = par[v];
    for (let i = start[v]; i < start[v + 1]; i++) {
      const ch = adj[i];
      if (ch === p) continue;
      const a = A[ch], b = B[ch], c = C[ch];
      const X = (a + b) % MOD;
      const Y = (b + c) % MOD;
      const Z = a;
      const s01 = (S0 + S1) % MOD;
      const nS0 = mul(S0, X);
      const nS1 = (mul(S1, X) + mul(s01, Z)) % MOD;
      const nS2 = (mul(S2, (X + Z) % MOD) + mul(s01, Y)) % MOD;
      S0 = nS0; S1 = nS1; S2 = nS2;
    }
    A[v] = S2; B[v] = S0; C[v] = S1;
  }

  const ans = (A[0] + B[0]) % MOD;
  process.stdout.write(ans + "\n");
}
