for (let i = 0; i < n; i++) a[i] = nextInt();
const eu = new Int32Array(n - 1), ev = new Int32Array(n - 1);
const deg = new Int32Array(n + 1);
for (let i = 0; i < n - 1; i++) {
  const u = nextInt() - 1, v = nextInt() - 1;
  eu[i] = u; ev[i] = v; deg[u]++; deg[v]++;
}
const adjStart = new Int32Array(n + 1);
for (let i = 0; i < n; i++) adjStart[i + 1] = adjStart[i] + deg[i];
const fill = new Int32Array(n);
const adjList = new Int32Array(2 * (n - 1));
for (let i = 0; i < n - 1; i++) {
  const u = eu[i], v = ev[i];
  adjList[adjStart[u] + fill[u]++] = v;
  adjList[adjStart[v] + fill[v]++] = u;
}

const order = new Int32Array(n), par = new Int32Array(n);
par[0] = -1;
let head = 0, tail = 0;
order[tail++] = 0;
const visited = new Uint8Array(n);
visited[0] = 1;
while (head < tail) {
  const v = order[head++];
  for (let j = adjStart[v]; j < adjStart[v + 1]; j++) {
    const c = adjList[j];
    if (!visited[c]) { visited[c] = 1; par[c] = v; order[tail++] = c; }
  }
}
const sz = new Int32Array(n);
for (let i = n - 1; i >= 0; i--) {
  const v = order[i];
  sz[v] += 1;
  if (par[v] >= 0) sz[par[v]] += sz[v];
}

const down = new Int32Array(n), up = new Int32Array(n);

function check(x) {
  for (let i = n - 1; i >= 0; i--) {
    const v = order[i];
    if (a[v] < x) { down[v] = 0; continue; }
    let S = 0, mx = 0;
    const p = par[v];
    for (let j = adjStart[v]; j < adjStart[v + 1]; j++) {
      const c = adjList[j]; if (c === p) continue;
      if (down[c] === sz[c]) S += sz[c];
      else if (down[c] > mx) mx = down[c];
    }
    down[v] = 1 + S + mx;
  }
  up[order[0]] = 0;
  for (let i = 0; i < n; i++) {
    const v = order[i];
    let S = 0, m1 = 0, m1i = -1, m2 = 0;
    const p = par[v];
    if (p >= 0) {
      const val = up[v], size = n - sz[v];
      if (val === size) S += size;
      else if (val > m1) { m2 = m1; m1 = val; m1i = p; }
      else if (val > m2) m2 = val;
    }
    for (let j = adjStart[v]; j < adjStart[v + 1]; j++) {
      const c = adjList[j]; if (c === p) continue;
      if (down[c] === sz[c]) S += sz[c];
      else {
        const val = down[c];
        if (val > m1) { m2 = m1; m1 = val; m1i = c; }
        else if (val > m2) m2 = val;
      }
    }
    const good = a[v] >= x;
    if (good && 1 + S + m1 >= k) return true;
    for (let j = adjStart[v]; j < adjStart[v + 1]; j++) {
      const c = adjList[j]; if (c === p) continue;
      if (!good) { up[c] = 0; continue; }
      let S2 = S, m = m1;
      if (down[c] === sz[c]) S2 -= sz[c];
      else if (m1i === c) m = m2;
      up[c] = 1 + S2 + m;
    }
  }
  return false;
}

const set = new Set();
for (let i = 0; i < n; i++) set.add(a[i]);
const vals = Array.from(set).sort((p, q) => p - q);
let lo = 0, hi = vals.length - 1, best = vals[0];
while (lo <= hi) {
  const mid = (lo + hi) >> 1;
  if (check(vals[mid])) { best = vals[mid]; lo = mid + 1; }
  else hi = mid - 1;
}
process.stdout.write(String(best) + "\n");
