const data = require('fs').readFileSync(0, 'utf8').split(/\s+/);
const n = parseInt(data[0]);
const k = parseInt(data[1]);
const MOD = 1000000007;

function mulmod(a, b) {
  const ah = Math.floor(a / 65536), al = a % 65536;
  return ((ah * b % MOD) * 65536 + al * b) % MOD;
}

const size = n + 2;
const inv = new Int32Array(size);
if (size > 1) inv[1] = 1;
for (let i = 2; i < size; i++) {
  inv[i] = MOD - mulmod(Math.floor(MOD / i), inv[MOD % i]) % MOD;
  if (inv[i] === MOD) inv[i] = 0;
}

const t = new Int32Array(n + 2);
t[1] = 1;
let sumAll = 1;
let S = 0;
for (let i = 2; i <= n; i++) {
  S = (S + t[i - 1]) % MOD;
  const rem = i - 1 - k;
  if (rem >= 1) {
    S = (S - t[rem] + MOD) % MOD;
  }
  t[i] = mulmod(S, inv[i - 1]);
  sumAll = (sumAll + t[i]) % MOD;
}

// (n-1)! and n!
let f = 1;
for (let i = 2; i <= n - 1; i++) {
  f = mulmod(f, i);
}
const n1fact = f;
const nfact = n >= 1 ? mulmod(n1fact, n) : 1;

let ans = (nfact - mulmod(n1fact, sumAll)) % MOD;
ans = ((ans % MOD) + MOD) % MOD;
console.log(ans.toString());
