function gen(arr) {
  const k = arr.length;
  const total = 1 << k;
  const res = new Float64Array(total);
  res[0] = 0;
  for (let i = 0; i < k; i++) {
    const bit = 1 << i;
    const v = arr[i];
    for (let mask = 0; mask < bit; mask++) {
      let s = res[mask] + v;
      if (s >= m) s -= m;
      res[bit | mask] = s;
    }
  }
  return res;
}

const A = gen(a.slice(0, h1));
const B = gen(a.slice(h1));

const Bs = Array.from(B);
Bs.sort((x, y) => x - y);
const len = Bs.length;
const maxB = Bs[len - 1];

