const fs = require('fs');

function main() {
  const buf = fs.readFileSync(0);
  let pos = 0;
  const len = buf.length;
  function nextInt() {
    while (pos < len && (buf[pos] < 48 || buf[pos] > 57)) pos++;
    let x = 0;
    while (pos < len && buf[pos] >= 48 && buf[pos] <= 57) {
      x = x * 10 + (buf[pos] - 48);
      pos++;
    }
    return x;
  }

  const n = nextInt(), m = nextInt();
  const f = new Uint8Array(n + 1);
  for (let i = 1; i <= n; i++) f[i] = nextInt();

  const ea = new Int32Array(m), eb = new Int32Array(m);
  const outStart = new Int32Array(n + 2), inStart = new Int32Array(n + 2);
  for (let i = 0; i < m; i++) {
    const a = nextInt(), b = nextInt();
    ea[i] = a; eb[i] = b;
    outStart[a + 1]++; inStart[b + 1]++;
  }
  for (let i = 1; i <= n + 1; i++) { outStart[i] += outStart[i - 1]; }
  for (let i = 1; i <= n + 1; i++) { inStart[i] += inStart[i - 1]; }
  const outAdj = new Int32Array(m), inAdj = new Int32Array(m);
  const posOut = new Int32Array(n + 2), posIn = new Int32Array(n + 2);
  for (let i = 0; i <= n + 1; i++) { posOut[i] = outStart[i]; posIn[i] = inStart[i]; }
  for (let i = 0; i < m; i++) {
    outAdj[posOut[ea[i]]++] = eb[i];
    inAdj[posIn[eb[i]]++] = ea[i];
  }

  const A = new Uint8Array(n + 1);
  const B = new Uint8Array(n + 1);
  const stack = new Int32Array(n + 1);
  let sp = 0;

  // forward: from assignment nodes, propagate to nodes with f != 1
  for (let i = 1; i <= n; i++) {
    if (f[i] === 1) { A[i] = 1; stack[sp++] = i; }
  }
  while (sp > 0) {
    const u = stack[--sp];
    for (let j = outStart[u]; j < outStart[u + 1]; j++) {
      const w = outAdj[j];
      if (f[w] !== 1 && !A[w]) { A[w] = 1; stack[sp++] = w; }
    }
  }

  // backward: from use nodes, propagate backwards; a node w can extend backwards
  // only if f[w] != 1 (since w would be an intermediate/end node after the start)
  sp = 0;
  for (let i = 1; i <= n; i++) {
    if (f[i] === 2) { B[i] = 1; stack[sp++] = i; }
  }
  while (sp > 0) {
    const w = stack[--sp];
    if (f[w] === 1) continue;
    for (let j = inStart[w]; j < inStart[w + 1]; j++) {
      const v = inAdj[j];
      if (!B[v]) { B[v] = 1; stack[sp++] = v; }
    }
  }

  const out = Buffer.allocUnsafe(2 * n);
  let p = 0;
  for (let i = 1; i <= n; i++) {
    out[p++] = (A[i] && B[i]) ? 49 : 48;
    out[p++] = 10;
  }
  process.stdout.write(out);
}

main();
```

