const data = require('fs').readFileSync(0, 'utf8').split('\n');
const n = parseInt(data[0].trim());
const s = data[1].trim();
const m = s.length;

// prefix function
const pi = new Array(m).fill(0);
for (let i = 1; i < m; i++) {
    let j = pi[i-1];
    while (j > 0 && s[i] !== s[j]) j = pi[j-1];
    if (s[i] === s[j]) j++;
    pi[i] = j;
}

// automaton transitions for states 0..m-1
const trans = [];
for (let st = 0; st < m; st++) {
    trans.push([0,0]);
    for (let c = 0; c < 2; c++) {
        const ch = c === 0 ? '0' : '1';
        if (s[st] === ch) {
            trans[st][c] = st + 1;
        } else if (st === 0) {
            trans[st][c] = 0;
        } else {
            trans[st][c] = trans[pi[st-1]][c];
        }
    }
}

let total = 0n;
for (let start = 0; start < m; start++) {
    let dp = new Array(m).fill(0n);
    dp[start] = 1n;
    for (let step = 0; step < n; step++) {
        const nd = new Array(m).fill(0n);
        for (let st = 0; st < m; st++) {
            if (dp[st] === 0n) continue;
            for (let c = 0; c < 2; c++) {
                const to = trans[st][c];
                if (to === m) continue;
                nd[to] += dp[st];
            }
        }
        dp = nd;
    }
    total += dp[start];
}

const totalStrings = 1n << BigInt(n);
console.log((totalStrings - total).toString());
