for(let i=0;i<size;i++){ coverArr[i]=cover(i); pcArr[i]=pc(i); }

let dp = [];
for(let i=0;i<size;i++){ dp.push(new Int32Array(size).fill(INF)); }
for(let cur=0;cur<size;cur++){
  const cv = coverArr[cur];
  if(pcArr[cur] < dp[cur][cv]) dp[cur][cv] = pcArr[cur];
}

for(let col=1; col<cols; col++){
  const ndp = [];
  for(let i=0;i<size;i++){ ndp.push(new Int32Array(size).fill(INF)); }
  for(let cur=0;cur<size;cur++){
    const row = dp[cur];
    for(let cov=0;cov<size;cov++){
      const v = row[cov];
      if(v>=INF) continue;
      for(let next=0;next<size;next++){
        if(((cov|next)&full) !== full) continue;
        const nc = (coverArr[next] | cur) & full;
        const nv = v + pcArr[next];
        if(nv < ndp[next][nc]) ndp[next][nc] = nv;
      }
    }
  }
  dp = ndp;
}

let best = INF;
for(let cur=0;cur<size;cur++){
  if(dp[cur][full] < best) best = dp[cur][full];
}
console.log(String(n*m - best));
